INSERT INTO feature VALUES('shell-blocks','syntax','Shell blocks #!{ … }',NULL,'declined','ordinary',NULL,'Declined by #1057: the shell block, `#!{ … }`, and its host escape parsed a command language that the lowering refused at every use, so the `shell_block` and `host_escape` rules, their thirteen sub-forms and the labeler''s shell mode are deleted. A `#!` that opens no shebang is an unknown token. Shell blocks return with a designed command fragment, its lowering to a process effect and a measured grammar (#3569).',NULL,NULL,NULL,'#3569');
